function x = equil_x0(L, LX, profiles_q)
    if nargin < 3
        profiles_q = zeros(L.Nq * (3 + L.P.Nb + L.P.Ns), 1);

        %% Initial guess 
        beta0 = LX.kinetic_profiles.beta(0);
        % needs to not be singular!
        q0 = LX.qfun(0);
        % P
        profiles_q((2*L.Nq+1:3*L.Nq)) = (-1 + sqrt(1+LX.Sbc(1)^2 * LX.eps_val^2)) .* L.r_q / LX.eps_val^2; % positive branch
        switch func2str(L.P.equation_of_state)
            case 'isotropic'
                % The order is such that we solve the uncoupled equations first:
                % 1) P, 2) t2, 3) delta
                % t2
                profiles_q((1:L.Nq)) = (beta0 - (1 + 2 *LX.Sbc(1)^2 * LX.eps_val^2)/q0^2) * L.r_q.^2;
                % Delta
                profiles_q((L.Nq+1:2*L.Nq)) = (LX.eps_val*(-1 + 4*beta0*q0^2)*LX.Sbc(1) + (1 + 4*beta0*q0^2)*sqrt(1 + ...
                LX.eps_val^2*LX.Sbc(1)^2))/(8.*(-2*LX.eps_val*LX.Sbc(1) - 3*LX.eps_val^3*LX.Sbc(1)^3 + ...
                sqrt(1 + LX.eps_val^2*LX.Sbc(1)^2) + 3*LX.eps_val^2*LX.Sbc(1)^2*sqrt(1 + ...
                LX.eps_val^2*LX.Sbc(1)^2))) .* L.r_q.^2;
            case 'parallel_rotating'
                % Assumed N_S >= 3, N_B >= 2
                % P
                profiles_q((2*L.Nq+1:3*L.Nq)) = (-1 + sqrt(1+LX.Sbc(1)^2 * LX.eps_val^2)) .* L.r_q / LX.eps_val^2; % positive branch
                beta0 = LX.kinetic_profiles.beta(0);
                q0 = LX.qfun(0);
                % t2 
                profiles_q((1:L.Nq)) = (beta0 + (-1+beta0^2)^3*(1 + 2 *LX.Sbc(1)^2 * LX.eps_val^2)/q0^2) * L.r_q.^2;
                % Delta
                profiles_q((L.Nq+1:2*L.Nq)) = L.r_q.^2*(-(sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2).*(q0.^2.*beta0.*(8 + (9 - 12.*LX.Sbc(2) + 4.*beta0).*LX.eps_val.^2 + 3.*(-3 + 4.*LX.Sbc(2)).*beta0.*LX.eps_val.^4) + 2.*(-1 + beta0.*LX.eps_val.^2).^3.*(-2 - 5.*beta0.*LX.eps_val.^2 + 4.*beta0.^2.*LX.eps_val.^4))) + LX.Sbc(1).*LX.eps_val.*(q0.^2.*beta0.*(-8 - (27 + 4.*beta0).*LX.eps_val.^2 + 27.*beta0.*LX.eps_val.^4) - 4.*(-1 + beta0.*LX.eps_val.^2).^3.*(1 - beta0.*LX.eps_val.^2 + 3.*beta0.^2.*LX.eps_val.^4) + 4.*LX.Sbc(2).*(-1 + beta0.*LX.eps_val.^2).*(-32 - 3.*(-26 + q0.^2).*beta0.*LX.eps_val.^2 - 60.*beta0.^2.*LX.eps_val.^4 + 14.*beta0.^3.*LX.eps_val.^6)) + 2.*LX.Sbc(1).^3.*LX.eps_val.^3.*(-1 + beta0.*LX.eps_val.^2).*(16.*LX.Sbc(2).*(-1 + beta0.*LX.eps_val.^2).^2.*(-5 + 2.*beta0.*LX.eps_val^2) + beta0.*LX.eps_val.^2.*(18.*q0.^2 - (-1 + beta0.*LX.eps_val.^2).^2.*(-7 + 10.*beta0.*LX.eps_val.^2))) - 2.*LX.Sbc(1).^2.*LX.eps_val.^2.*sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2).*(-1 + beta0.*LX.eps_val.^2).*(-8.*LX.Sbc(2).*(2 - 3.*beta0.*LX.eps_val.^2 + beta0.^3.*LX.eps_val.^6) + beta0.*LX.eps_val.^2.*(-18.*q0.^2 + (-1 + beta0.*LX.eps_val.^2).^2.*(-7 + 10.*beta0.*LX.eps_val.^2))))./(8..*(-1 + beta0.*LX.eps_val.^2).*(3.*LX.Sbc(1).^3.*LX.eps_val.^3.*(-4 + beta0.*LX.eps_val.^2).*(-1 + beta0.*LX.eps_val.^2).^2 - 3.*LX.Sbc(1).^2.*LX.eps_val.^2.*sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2).*(-4 + beta0.*LX.eps_val.^2).*(-1 + beta0.*LX.eps_val.^2).^2 + sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2).*(4 - 3.*(3 + q0.^2).*beta0.*LX.eps_val.^2 + 6.*beta0.^2.*LX.eps_val.^4 - beta0.^3.*LX.eps_val.^6) + LX.Sbc(1).*LX.eps_val.*(-8 - 3.*(-6 + q0.^2).*beta0.*LX.eps_val.^2 - 12.*beta0.^2.*LX.eps_val.^4 + 2.*beta0.^3.*LX.eps_val.^6)));
                % B0
                profiles_q((3*L.Nq+1:4*L.Nq)) = L.r_q.^2*-0.25.*(LX.eps_val.*(-1 + beta0.*LX.eps_val.^2).*(3 + (4.*beta0)./(-1 + beta0.*LX.eps_val.^2) + (2.*(1 + 2.*LX.Sbc(1).^2.*LX.eps_val.^2).*(-1 + beta0.*LX.eps_val.^2).^2)./q0.^2 + 6.*LX.Sbc(1).*LX.eps_val.*(LX.Sbc(1).*LX.eps_val + sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2)) - 4.*beta0.*LX.eps_val.^2.*(LX.Sbc(1).*LX.eps_val + sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2)).^2 + 3.*beta0.^2.*LX.eps_val.^4.*(LX.Sbc(1).*LX.eps_val + sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2)).^2 - 2.*beta0.*LX.eps_val.^2.*(-1 + beta0.*LX.eps_val.^2).*(LX.Sbc(1).*LX.eps_val + sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2)).^2 - (-1 + beta0.*LX.eps_val.^2).^2.*(LX.Sbc(1).*LX.eps_val + sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2)).^2 - (4.*(beta0 + ((1 + 2.*LX.Sbc(1).^2.*LX.eps_val.^2).*(-1 + beta0.*LX.eps_val.^2).^3)./q0.^2))./(-1 + beta0.*LX.eps_val.^2) + (-(sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2).*(q0.^2.*beta0.*(8 + (9 - 12.*LX.Sbc(2) + 4.*beta0).*LX.eps_val.^2 + 3.*(-3 + 4.*LX.Sbc(2)).*beta0.*LX.eps_val.^4) + 2.*(-1 + beta0.*LX.eps_val.^2).^3.*(-2 - 5.*beta0.*LX.eps_val.^2 + 4.*beta0.^2.*LX.eps_val.^4))) + LX.Sbc(1).*LX.eps_val.*(q0.^2.*beta0.*(-8 - (27 + 4.*beta0).*LX.eps_val.^2 + 27.*beta0.*LX.eps_val.^4) - 4.*(-1 + beta0.*LX.eps_val.^2).^3.*(1 - beta0.*LX.eps_val.^2 + 3.*beta0.^2.*LX.eps_val.^4) + 4.*LX.Sbc(2).*(-1 + beta0.*LX.eps_val.^2).*(-32 - 3.*(-26 + q0.^2).*beta0.*LX.eps_val.^2 - 60.*beta0.^2.*LX.eps_val.^4 + 14.*beta0.^3.*LX.eps_val.^6)) + 2.*LX.Sbc(1).^3.*LX.eps_val.^3.*(-1 + beta0.*LX.eps_val.^2).*(16.*LX.Sbc(2).*(-1 + beta0.*LX.eps_val.^2).^2.*(-5 + 2.*beta0.*LX.eps_val.^2) + beta0.*LX.eps_val.^2.*(18.*q0.^2 - (-1 + beta0.*LX.eps_val.^2).^2.*(-7 + 10.*beta0.*LX.eps_val.^2))) - 2.*LX.Sbc(1).^2.*LX.eps_val.^2.*sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2).*(-1 + beta0.*LX.eps_val.^2).*(-8.*LX.Sbc(2).*(2 - 3.*beta0.*LX.eps_val.^2 + beta0.^3.*LX.eps_val.^6) + beta0.*LX.eps_val.^2.*(-18.*q0.^2 + (-1 + beta0.*LX.eps_val.^2).^2.*(-7 + 10.*beta0.*LX.eps_val.^2))))./(2..*(-1 + beta0.*LX.eps_val.^2).*(3.*LX.Sbc(1).^3.*LX.eps_val.^3.*(-4 + beta0.*LX.eps_val.^2).*(-1 + beta0.*LX.eps_val.^2).^2 - 3.*LX.Sbc(1).^2.*LX.eps_val.^2.*sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2).*(-4 + beta0.*LX.eps_val.^2).*(-1 + beta0.*LX.eps_val.^2).^2 + sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2).*(4 - 3.*(3 + q0.^2).*beta0.*LX.eps_val.^2 + 6.*beta0.^2.*LX.eps_val.^4 - beta0.^3.*LX.eps_val.^6) + LX.Sbc(1).*LX.eps_val.*(-8 - 3.*(-6 + q0.^2).*beta0.*LX.eps_val.^2 - 12.*beta0.^2.*LX.eps_val.^4 + 2.*beta0.^3.*LX.eps_val.^6)))));
                % B1
                profiles_q((4*L.Nq+1:5*L.Nq)) = L.r_q*((-1 + beta0.*LX.eps_val.^2).*(LX.Sbc(1).*LX.eps_val + sqrt(1 + LX.Sbc(1).^2.*LX.eps_val.^2)));
            case 'biMaxwellian'
                A0 = LX.kinetic_profiles.Ah(0);
                Bc0 = LX.kinetic_profiles.Bc(0);
                % Assumed N_S >= 3
                % t2
                profiles_q((1:L.Nq)) = (beta0./((1 - A0.*(1 - 1./Bc0)).*Bc0) + ((1 + 2.*LX.Sbc(1).^2.*LX.eps_val.^2).*(-1 + (-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*beta0.*LX.eps_val.^2).^3)./q0.^2) * L.r_q.^2;
                % Delta
                delta0 = (-0.125.*(q0.^2.*((4.*(-1 + ((2.*A0.^2)./((1 - A0.*(1 - 1./Bc0)).^3.*Bc0.^3) - (2.*A0)./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)).*beta0.*LX.eps_val.^2).^2.*(-1 + (-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*beta0.*LX.eps_val.^2).^3.*(3.*((-6.*A0.^3)./((1 - A0.*(1 - 1./Bc0)).^4.*Bc0.^4) + (6.*A0.^2)./((1 - A0.*(1 - 1./Bc0)).^3.*Bc0.^3)).*(-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*beta0.^2.*LX.eps_val.^4.*(-1 + (-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*beta0.*LX.eps_val.^2) - (-1 + ((2.*A0.^2)./((1 - A0.*(1 - 1./Bc0)).^3.*Bc0.^3) - (2.*A0)./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)).*beta0.*LX.eps_val.^2).*(2 + beta0.*LX.eps_val.^2.*((-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*(5 - 4.*(-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*beta0.*LX.eps_val.^2) + 3.*((2.*A0.^2)./((1 - A0.*(1 - 1./Bc0)).^3.*Bc0.^3) - (2.*A0)./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)).*(-4 + 3.*(-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*beta0.*LX.eps_val.^2)))))./q0.^2 - beta0.*((8.*(-1 + ((2.*A0.^2)./((1 - A0.*(1 - 1./Bc0)).^3.*Bc0.^3) - (2.*A0)./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)).*beta0.*LX.eps_val.^2).^2.*(-3.*((-6.*A0.^3)./((1 - A0.*(1 - 1./Bc0)).^4.*Bc0.^4) + (6.*A0.^2)./((1 - A0.*(1 - 1./Bc0)).^3.*Bc0.^3)).*(-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*beta0.^2.*LX.eps_val.^4.*(-1 + (-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*beta0.*LX.eps_val.^2) + (-1 + ((2.*A0.^2)./((1 - A0.*(1 - 1./Bc0)).^3.*Bc0.^3) - (2.*A0)./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)).*beta0.*LX.eps_val.^2).*(-4 + beta0.*LX.eps_val.^2.*((-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*(3 - 2.*(-(A0./((1 - A0.*(1 - 1./Bc0)).^2.*Bc0.^2)) + 1./((1 - A0.*(1 - 1./Bc0)).*Bc0)).*beta0.*LX.eps_val.^2